import sys; sys.path.insert(0, '_tools'); from spec import enrich
enrich('el-deleite-integral', 'A',
 [dict(t=1050, e=1118, titulo='Ya te salvaron, ahora te toca deleitar a Dios', txt='Eso sigue vigente. Pero el desafío para nosotros, para la iglesia este año, es que nosotros sí deleitemos a Dios. Porque ahora, después de que somos salvos, vamos a ver: para el inconverso, el Año del Deleite es «Dios te quiere salvar». No es que yo tengo que arreglar las cosas con mi mujer, que tengo que arreglar esto. No, no, no. Dios no te está pidiendo que lo deleites: Dios te quiere salvar. Eso es para el inconverso. Pero para el salvo no es así. Para el salvo es: ya te salvaron, ahora te toca deleitar a Dios. Y si deleitas a Dios, vas a tener dos cosas: en la vida presente, bendición; y en la vida futura, en la segunda venida, acceso a las bodas. Vas a ser parte de la novia del Cordero.'),
  dict(t=2801, e=2880, titulo='Un año de limpieza y de liberación', txt='Esa palabra «santificar» es la palabra […], que significa limpiar: «El mismo Dios de paz os limpie por completo». O sea, este es un año de limpieza, este es un año de liberación. Este es un año de ministración. Este es un año donde se van a romper cadenas, se van a romper lazos, se van a romper ataduras. Es que si no, no vamos a poder agradar a Dios, hermano. Le voy a leer otro versículo, Segunda Corintios 7:1: «Por tanto, amados, teniendo estas promesas, limpiémonos de toda inmundicia de la carne y del espíritu, perfeccionando la santidad en el temor del Señor». Entonces el espíritu también se puede contaminar. Uno de los temas que se tendrían que desprender de aquí es cómo se contamina un espíritu. Y la iniquidad es una de las formas de […] hechicería, idolatría. Hay muchas formas de que se puede contaminar.'),
  dict(t=3699, e=3762, titulo='El deleite del espíritu es adorar a Dios', txt='Porque el deleite del espíritu, según lo que vemos en el pasaje del Señor en el monte de la tentación, era adorar a Dios. Era adorar a Dios. Y lo que el enemigo quería era desenfocarlo de ahí. Si lo desenfocaba en la adoración, entonces lo desenfocaba en las demás cosas. Entonces miremos ahora, por ejemplo, la iglesia emergente. Una de las cosas que se ha atacado es la adoración, porque en lugar de adoración se ha metido entretenimiento cristiano. «¿Cómo vamos a hacer los cultos? Como le gusta a los hermanos». […] Al final, toda la música la creó Dios, dicen ellos. Sí, toda la música la creó Dios, pero a Luzbel también lo creó Dios.')],
 [dict(t=1502, txt='El Señor va a tener que trabajar con nuestros deseos, porque el Señor sí nos quiere cerca. Pero no te quiere a la fuerza.'),
  dict(t=2392, txt='Si uno no logra tener ese deleite integral, puede hacer cosas, pero las va a hacer cargado y cansado: se va a volver religioso, y no se va a estar deleitando en lo que hace.'),
  dict(t=4146, txt='Nosotros ya somos fruto del deleite de Dios para salvación, pero ahora nos toca deleitar a Dios para bendición, para galardones, para boda.')],
 ['Ya fuiste salvo, y ahora te toca deleitar a Dios: ¿qué parte de tu semana le ofreces con gozo y cuál haces solo por cumplir o por quedar bien?',
  '¿Cómo están tu espíritu, tu alma y tu cuerpo: alineados o en contradicción? ¿Cuál de los tres necesitas poner en orden delante de Dios esta semana?',
  'La Palabra habla de limpiarnos de toda inmundicia de la carne y del espíritu: ¿qué le pedirías hoy al Señor que limpie en ti?'],
 inicio=149)
